parameters.jsCode:
const LS = `Qual serviço deseja agendar? Responda com o número.Se forem vários exames separe por vírgula.Ex: 1,2,3.\n1. Consulta médica\n2. ECG\n3. Teste Ergométrico\n4. Ecocardiograma Doppler Transtorácico\n5. Ecocardiograma Doppler Carótidas e Vertebrais\n6. MAPA 24 horas\n7. Holter 24 horas`;

const LM_CONSULTA = `Preferência de médico? Responda com número ou diga sem preferência:\n1. Dr. Amberson Vieira de Assis (Cardiologista)\n2. Dr. Cesar Paleari (Cardiologista)\n3. Dra. Fabiana Impaléa Paleari (Cardiologista)\n4. Dr. Ilnei Pereira Filho (Cardiologista)\n5. Dr. José Antonio Carvalho (Cardiologista)\n6. Dr. Leonardo Guillermo Cal (Cardiologista/Pediátrico)\n7. Dr. Marcos Ferranti Smaniotto (Cardiologista)\n8. Dra. Sheila Montano Veja (Endocrinologista)`;

const LM_ECG = `Preferência de médico? Responda com número ou diga sem preferência:\n1. Dr. Amberson Vieira de Assis (Cardiologista)\n2. Dr. Cesar Paleari (Cardiologista)\n3. Dra. Fabiana Impaléa Paleari (Cardiologista)\n4. Dr. Ilnei Pereira Filho (Cardiologista)\n5. Dr. José Antonio Carvalho (Cardiologista)\n6. Dr. Leonardo Guillermo Cal (Cardiologista/Pediátrico)\n7. Dr. Marcos Ferranti Smaniotto (Cardiologista)`;

const LM_ERGOMETRICO = `Preferência de médico? Responda com número ou diga sem preferência:\n1. Dr. Cesar Paleari (Cardiologista)\n2. Dra. Fabiana Impaléa Paleari (Cardiologista)\n3. Dr. Ilnei Pereira Filho (Cardiologista)\n4. Dr. José Antonio Carvalho (Cardiologista)\n5. Dr. Leonardo Guillermo Cal (Cardiologista/Pediátrico)\n6. Dr. Marcos Ferranti Smaniotto (Cardiologista)`;

const LM_ECO_TRANSTORACICO = `Preferência de médico? Responda com número ou diga sem preferência:\n1. Dr. José Antonio Carvalho (Cardiologista)\n2. Dr. Leonardo Guillermo Cal (Cardiologista/Pediátrico)\n3. Dra. Vanessa Wandeur (Cardiologista)`;

const LM_ECO_CAROTIDAS = `Preferência de médico? Responda com número ou diga sem preferência:\n1. Dr. José Antonio Carvalho (Cardiologista)\n2. Dr. Leonardo Guillermo Cal (Cardiologista/Pediátrico)\n3. Dra. Vanessa Wandeur (Cardiologista)`;

const LM_MAPA = `Preferência de médico? Responda com número ou diga sem preferência:\n1. Dr. Amberson Vieira de Assis (Cardiologista)\n2. Dr. Cesar Paleari (Cardiologista)\n3. Dra. Fabiana Impaléa Paleari (Cardiologista)\n4. Dr. Ilnei Pereira Filho (Cardiologista)\n5. Dr. José Antonio Carvalho (Cardiologista)\n6. Dr. Leonardo Guillermo Cal (Cardiologista/Pediátrico)\n7. Dr. Marcos Ferranti Smaniotto (Cardiologista)`;

const LM_HOLTER = `Preferência de médico? Responda com número ou diga sem preferência:\n1. Dr. Amberson Vieira de Assis (Cardiologista)\n2. Dr. Cesar Paleari (Cardiologista)\n3. Dra. Fabiana Impaléa Paleari (Cardiologista)\n4. Dr. Ilnei Pereira Filho (Cardiologista)\n5. Dr. José Antonio Carvalho (Cardiologista)\n6. Dr. Leonardo Guillermo Cal (Cardiologista/Pediátrico)\n7. Dr. Marcos Ferranti Smaniotto (Cardiologista)`;

const texto = $input.first().json.output || '';

const temResumo = texto.includes('[ENVIAR_RECEPCAO]');
const temDuvidaValor = texto.includes('[DUVIDA_VALOR]');

let msgPaciente = texto;
let blocoResumo = '';
let blocoDuvidaValor = '';

if (temResumo) {
  const partes = msgPaciente.split('[ENVIAR_RECEPCAO]');
  msgPaciente = partes[0].trim();
  const depois = partes[1] || '';
  blocoResumo = depois.includes('[FIM_RESUMO]')
    ? depois.split('[FIM_RESUMO]')[0].trim()
    : depois.trim();
}

if (temDuvidaValor) {
  const partes = msgPaciente.split('[DUVIDA_VALOR]');
  msgPaciente = partes[0].trim();
  const depois = partes[1] || '';
  blocoDuvidaValor = depois.includes('[FIM_DUVIDA]')
    ? depois.split('[FIM_DUVIDA]')[0].trim()
    : depois.trim();
}

// ATUALIZADO 01/ago: remove o marcador [NOVA_PESSOA] do texto antes de
// enviar ao paciente — ele existe só pra sinalizar o reset de dados pro
// resto do workflow, não é conteúdo de conversa.
msgPaciente = msgPaciente.replace(/\[NOVA_PESSOA\]/g, '').trim();

msgPaciente = msgPaciente
  .replace(/\[LISTA_SERVICOS\]/g, LS)
  .replace(/\[LISTA_MEDICOS_CONSULTA\]/g, LM_CONSULTA)
  .replace(/\[LISTA_MEDICOS_ECG\]/g, LM_ECG)
  .replace(/\[LISTA_MEDICOS_ERGOMETRICO\]/g, LM_ERGOMETRICO)
  .replace(/\[LISTA_MEDICOS_ECO_TRANSTORACICO\]/g, LM_ECO_TRANSTORACICO)
  .replace(/\[LISTA_MEDICOS_ECO_CAROTIDAS\]/g, LM_ECO_CAROTIDAS)
  .replace(/\[LISTA_MEDICOS_MAPA\]/g, LM_MAPA)
  .replace(/\[LISTA_MEDICOS_HOLTER\]/g, LM_HOLTER);

const itens = msgPaciente.split('|||').map(p => p.trim()).filter(p => p !== '');
const total = itens.length;

if (total === 0) {
  return [{
    item: '',
    temResumo,
    blocoResumo,
    temDuvidaValor,
    blocoDuvidaValor,
    isUltima: true,
    totalItens: 0,
    indice: 0,
    telefone: $('Coleta').item.json.telefone
  }];
}

return itens.map((p, i) => ({
  item: p,
  temResumo,
  blocoResumo,
  temDuvidaValor,
  blocoDuvidaValor,
  isUltima: i === total - 1,
  totalItens: total,
  indice: i,
  telefone: $('Coleta').item.json.telefone
}));

return [{
  item: 'Desculpe, tive um problema técnico. Pode repetir sua mensagem?',
  telefone: $('Coleta').item.json.telefone || ''
}];

const blocoOriginal = $('SEPARA MENSAGENS').item.json.blocoResumo || '';
// Normaliza: se o modelo usar || ou ||| como separador em vez de quebra de linha,
// converte qualquer sequência de pipes em quebra de linha antes de extrair os campos.
const bloco = blocoOriginal.replace(/\|+/g, '\n');
function extrair(campo) {
  // [ \t]* em vez de \s* -> NÃO atravessa quebra de linha quando o campo vem vazio.
  // ([^\n]*) com * em vez de + -> aceita campo vazio e retorna string vazia,
  // em vez de sair capturando a linha seguinte (ex.: telefone caindo em exames).
  const regex = new RegExp(campo + ':[ \\t]*([^\\n]*)');
  const match = bloco.match(regex);
  return match ? match[1].replace(/\|/g, '').trim() : '';
}

const nome = extrair('nome');
const nascimento = extrair('nascimento');
const cpf = extrair('cpf');
let servico = extrair('servico');
let medico = extrair('medico');
let convenio = extrair('convenio');
const email = extrair('email');
let preferencia = extrair('preferencia');
const tipo_solicitacao = extrair('tipo') || 'novo';
const data_consulta_atual = extrair('data_atual');
const nova_data_pretendida = extrair('nova_data');
const exames_solicitados = extrair('exames_solicitados');

// ─────────────────────────────────────────
// CORREÇÃO FINAL COM VALORES DETERMINÍSTICOS (máquina de estado)
// Se a máquina de estado calculou algum desses valores em código (a partir do
// número que o paciente realmente digitou), ele é mais confiável que o que a
// IA escreveu no bloco final — substitui aqui, silenciosamente, sem aviso.
// ─────────────────────────────────────────
try {
  const valoresFinais = $('BUSCA VALORES FINAIS').item.json;
  if (valoresFinais.servico_escolhido) servico = valoresFinais.servico_escolhido;
  if (valoresFinais.medico_escolhido) medico = valoresFinais.medico_escolhido.replace(/\s*\(.*?\)\s*$/, '');
  const convenioFinal = valoresFinais.qual_convenio_confirmado || valoresFinais.cartao_desconto_confirmado;
  if (convenioFinal) convenio = convenioFinal;
  if (valoresFinais.dia_periodo_confirmado) {
    if (valoresFinais.dia_periodo_confirmado === 'Sem preferência') {
      preferencia = 'Sem preferência';
    } else {
      // Formato salvo é "Dia - Período" (como mostrado ao paciente) — o resto
      // do sistema (incluindo a validação de agenda) espera "Período, Dia".
      const partesData = valoresFinais.dia_periodo_confirmado.split(' - ');
      preferencia = partesData.length === 2 ? `${partesData[1]}, ${partesData[0]}` : valoresFinais.dia_periodo_confirmado;
    }
  }
} catch (e) {
  // Node não existe ainda (ex.: workflow antigo sem a máquina de estado) — segue com o que a IA escreveu.
}

// ─────────────────────────────────────────
// VALIDAÇÃO DE AGENDA POR MÉDICO (trava mecânica, não depende da IA acertar)
// Mesma tabela da seção REGRAS DE AGENDA POR MÉDICO do prompt.
// Se a IA errar médico ou dia/período, o card sai com um aviso visível
// em vez de passar batido para a recepção confirmar com o paciente.
// ─────────────────────────────────────────
function normaliza(texto) {
  return (texto || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '') // remove acentos
    .trim();
}

// Chaves normalizadas (sem acento) para bater com normaliza(medico) no lookup.
const AGENDA_POR_MEDICO = {
  [normaliza('Dr. Cesar Paleari')]: ['Manhã, Segunda-feira', 'Manhã, Terça-feira', 'Manhã, Quinta-feira', 'Manhã, Sexta-feira'],
  [normaliza('Dra. Fabiana Impaléa Paleari')]: ['Manhã, Segunda-feira', 'Manhã, Quinta-feira'],
  [normaliza('Dr. Ilnei Pereira Filho')]: ['Manhã, Segunda-feira', 'Tarde, Segunda-feira', 'Tarde, Terça-feira', 'Tarde, Quinta-feira', 'Manhã, Sexta-feira'],
  [normaliza('Dr. José Antonio Carvalho')]: ['Manhã, Segunda-feira', 'Tarde, Segunda-feira', 'Tarde, Terça-feira', 'Manhã, Quarta-feira', 'Tarde, Quinta-feira', 'Manhã, Sexta-feira'],
  [normaliza('Dr. Leonardo Guillermo Cal')]: ['Manhã, Segunda-feira', 'Manhã, Terça-feira', 'Manhã, Quarta-feira', 'Manhã, Quinta-feira', 'Manhã, Sexta-feira'],
  [normaliza('Dr. Marcos Ferranti Smaniotto')]: ['Tarde, Terça-feira', 'Tarde, Quarta-feira'],
  [normaliza('Dr. Amberson Vieira de Assis')]: ['Manhã, Quinta-feira'],
  [normaliza('Dra. Sheila Montano Veja')]: ['Tarde, Quinta-feira']
};

// Política de convênio de cada médico — usada para detectar quando o card fechou
// como Particular mas o médico escolhido na verdade aceita convênio (sinal forte
// de que o PASSO 6 — convênio ou particular — pode ter sido pulado pela IA).
const MEDICOS_SOMENTE_PARTICULAR = [
  normaliza('Dr. Amberson Vieira de Assis'),
  normaliza('Dra. Sheila Montano Veja')
];

// Só valida agendamento novo, com médico específico (não "sem preferência")
// e com dia/período específico (não "Sem preferência").
// Exceção: "Múltiplos exames" nunca tem médico/convênio/dia definidos — nunca validar esse caso.
const medicoNormalizado = normaliza(medico);
const preferenciaSemPreferencia = normaliza(preferencia).includes('sem preferencia');
const medicoSemPreferencia = medicoNormalizado.includes('sem preferencia')
  || medicoNormalizado.includes('a definir')
  || medicoNormalizado === '';
const servicoMultiplo = normaliza(servico).includes('multiplos exames');

// ─────────────────────────────────────────
// VALIDAÇÃO DE PASSO 6 PULADO (médico aceita convênio, mas fechou como particular
// SEM a pergunta "convênio ou particular" nunca ter sido feita nesta conversa —
// consultado na máquina de estado, node BUSCA FLAG CONVENIO. Isso evita alertar
// à toa quando o paciente escolheu particular de propósito, com a pergunta
// realmente apresentada.)
// ─────────────────────────────────────────
let perguntaConvenioFoiFeita = true; // padrão seguro: só alerta com confirmação explícita de que NÃO foi feita
try {
  const valorFlag = $('BUSCA FLAG CONVENIO').item.json.perguntou_convenio_particular;
  if (valorFlag === false) {
    perguntaConvenioFoiFeita = false;
  }
  // Se vier true, null ou undefined (dado ausente/incerto), mantém true — nunca alerta por incerteza.
} catch (e) {
  // Node não existe ainda (ex.: workflow antigo sem a máquina de estado) — mantém o padrão seguro.
}

let particularSuspeito = false;
if (!servicoMultiplo && !medicoSemPreferencia && !perguntaConvenioFoiFeita) {
  const convenioNormalizado = normaliza(convenio);
  const fechouComoParticular = convenioNormalizado.includes('particular');
  const medicoAceitaConvenio = !MEDICOS_SOMENTE_PARTICULAR.includes(medicoNormalizado);
  if (fechouComoParticular && medicoAceitaConvenio) {
    particularSuspeito = true;
  }
}

// ─────────────────────────────────────────
// VALIDAÇÃO DE PASSO 5 PULADO (médico específico registrado, mas a pergunta
// "Qual médico você prefere?" nunca foi enviada nesta conversa — consultado
// na máquina de estado, node BUSCA FLAG MEDICO.)
// ─────────────────────────────────────────
let perguntaMedicoFoiFeita = true; // padrão seguro: só alerta com confirmação explícita de que NÃO foi feita
try {
  const valorFlagMedico = $('BUSCA FLAG MEDICO').item.json.perguntou_medico;
  if (valorFlagMedico === false) {
    perguntaMedicoFoiFeita = false;
  }
} catch (e) {
  // Node não existe ainda (ex.: workflow antigo sem a máquina de estado) — mantém o padrão seguro.
}

let medicoNaoConfirmado = false;
if (!servicoMultiplo && !medicoSemPreferencia && !perguntaMedicoFoiFeita) {
  medicoNaoConfirmado = true;
}

function pareceVazioOuGenerico(valor) {
  const v = normaliza(valor);
  if (v === '') return true;
  const termosGenericos = ['sem identificacao', 'nao informado', 'nao informada', 'a definir', 'nao coletado', 'n/a', 'nao possui'];
  return termosGenericos.some(termo => v.includes(termo));
}

function nomeParaceNumero(valor) {
  // Detecta nome preenchido com dígitos (o paciente digitou CPF, telefone, data etc.
  // no campo de nome, ou a IA copiou o valor errado para o campo errado).
  const somenteDigitosEPontuacao = /^[\d\s.\-\/]+$/;
  return somenteDigitosEPontuacao.test((valor || '').trim()) && (valor || '').trim() !== '';
}

function nomeParacePreenchimentoInvalido(valor) {
  // Detecta respostas que claramente não são um nome completo real — pronomes,
  // confirmações soltas, ou palavras de preenchimento que a IA aceitou por engano
  // no lugar do nome (ex.: paciente respondeu "esse", "ok", "isso" a outra pergunta,
  // e a IA registrou isso como nome).
  const v = normaliza(valor);
  if (v === '') return false; // vazio já é pego por pareceVazioOuGenerico
  const PALAVRAS_INVALIDAS = [
    'esse', 'essa', 'esses', 'essas', 'isso', 'isto', 'aquele', 'aquela',
    'aqui', 'ali', 'la', 'ta', 'tah', 'ok', 'okay', 'sim', 'nao',
    'blz', 'vlw', 'obrigado', 'obrigada', 'oi', 'ola', 'certo', 'entendi'
  ];
  // Só marca como inválido se a resposta inteira (sem mais nada) for uma dessas palavras —
  // não bloqueia nomes reais que apenas contenham essas letras.
  return PALAVRAS_INVALIDAS.includes(v);
}

function contemLetra(valor) {
  // Nascimento e CPF nunca deveriam ter letra nenhuma — nem acentuada.
  return /[a-zA-ZÀ-ÖØ-öø-ÿ]/.test(valor || '');
}

function nascimentoPareceInvalido(valor) {
  // Detecta data de nascimento escrita por extenso ("Vinte e quatro") ou qualquer
  // texto com letra, e também formatos com poucos ou muitos dígitos demais.
  if (contemLetra(valor)) return true;
  const digitos = (valor || '').replace(/\D/g, '');
  // Aceita dd/mm/aaaa (8 dígitos), dd/mm/aa (6 dígitos), ou variações como "20 07 52" (6).
  return digitos.length < 6 || digitos.length > 8;
}

function cpfPareceInvalido(valor) {
  // CPF tem SEMPRE exatamente 11 dígitos — regra rígida, fácil de checar.
  if (contemLetra(valor)) return true;
  const digitos = (valor || '').replace(/\D/g, '');
  return digitos.length !== 11;
}

if (tipo_solicitacao === 'novo' && !servicoMultiplo && !medicoSemPreferencia && !preferenciaSemPreferencia) {
  const opcoesValidas = AGENDA_POR_MEDICO[medicoNormalizado];

  if (pareceVazioOuGenerico(preferencia)) {
    // O PASSO 7 (dia e período) foi pulado — a IA fechou o agendamento sem essa informação.
    medico = '⚠️ CONFERIR (dia/período não coletado — PASSO 7 pode ter sido pulado) — ' + medico;
  } else if (!opcoesValidas) {
    // Médico não reconhecido na tabela (nome digitado diferente, erro de grafia da IA, etc.)
    medico = '⚠️ CONFERIR (médico não reconhecido) — ' + medico;
  } else if (!opcoesValidas.some(op => normaliza(op) === normaliza(preferencia))) {
    // Médico reconhecido, mas o dia/período não bate com a agenda real dele
    medico = '⚠️ CONFERIR (fora da agenda) — ' + medico;
  } else if (particularSuspeito) {
    // Médico aceita convênio, mas o card fechou como particular — o PASSO 6
    // (convênio ou particular) pode ter sido pulado pela IA.
    medico = '⚠️ CONFERIR (particular, mas médico aceita convênio — confirmar se convênio foi oferecido) — ' + medico;
  } else if (medicoNaoConfirmado) {
    // A pergunta "Qual médico você prefere?" nunca foi enviada nesta conversa,
    // mas um médico específico foi registrado mesmo assim — sinal de pulo do PASSO 5.
    medico = '⚠️ CONFERIR (médico não confirmado — pergunta de médico pode ter sido pulada) — ' + medico;
  }
}

// ─────────────────────────────────────────
// EXAMES NO MESMO DIA — usa o valor CALCULADO EM CÓDIGO (determinístico,
// vindo da máquina de estado) em vez de confiar no que a IA escreveu no
// bloco final. Isso corrige o dado de verdade, sem precisar de aviso —
// só cai no aviso antigo se esse valor não existir (ex.: paciente respondeu
// em texto livre, fora do padrão numérico simples).
// ─────────────────────────────────────────
let exames_solicitados_final = exames_solicitados;
try {
  const valorDeterministico = $('BUSCA EXAMES CONFIRMADOS').item.json.exames_mesmo_dia_confirmado;
  if (valorDeterministico) {
    exames_solicitados_final = valorDeterministico;
  } else if (normaliza(servico).includes('consulta medica') && (exames_solicitados || '').trim() === '') {
    exames_solicitados_final = '⚠️ CONFERIR (resposta sobre exames no mesmo dia pode ter sido perdida — confirmar com o paciente)';
  }
} catch (e) {
  // Node não existe ainda (ex.: workflow antigo sem a máquina de estado) — mantém o comportamento anterior.
  if (normaliza(servico).includes('consulta medica') && (exames_solicitados || '').trim() === '') {
    exames_solicitados_final = '⚠️ CONFERIR (resposta sobre exames no mesmo dia pode ter sido perdida — confirmar com o paciente)';
  }
}

// ─────────────────────────────────────────
// VALIDAÇÃO DE IDENTIFICAÇÃO MÍNIMA (trava mecânica, não depende da IA acertar)
// A IA às vezes gera o bloco sem nome/nascimento/CPF reais, escrevendo texto
// genérico tipo "sem identificação" nesses campos, mesmo com instrução contrária.
// Se isso acontecer, marcamos o card com um aviso visível em vez de deixar
// passar como se os dados estivessem completos.
// ─────────────────────────────────────────

let identificacaoIncompleta = false;
if (tipo_solicitacao === 'novo') {
  // Agendamento novo (inclusive Múltiplos exames): coleta nome, nascimento e CPF.
  if (pareceVazioOuGenerico(nome) || nomeParaceNumero(nome) || nomeParacePreenchimentoInvalido(nome)
      || pareceVazioOuGenerico(nascimento) || nascimentoPareceInvalido(nascimento)
      || pareceVazioOuGenerico(cpf) || cpfPareceInvalido(cpf)) {
    identificacaoIncompleta = true;
  }
} else if (tipo_solicitacao === 'cancelamento' || tipo_solicitacao === 'remarcacao') {
  // Cancelamento/remarcação NUNCA coletam nascimento nem CPF — só nome e a data atual da consulta/exame.
  if (pareceVazioOuGenerico(nome) || nomeParaceNumero(nome) || nomeParacePreenchimentoInvalido(nome) || pareceVazioOuGenerico(data_consulta_atual)) {
    identificacaoIncompleta = true;
  }
}

const camposFaltando = tipo_solicitacao === 'novo'
  ? 'nome/nascimento/CPF'
  : 'nome/data da consulta ou exame';

function descreveProblema() {
  const problemas = [];
  if (nomeParaceNumero(nome) || nomeParacePreenchimentoInvalido(nome)) problemas.push(`nome inválido: "${nome}"`);
  else if (pareceVazioOuGenerico(nome)) problemas.push('nome não coletado');
  if (tipo_solicitacao === 'novo') {
    if (nascimentoPareceInvalido(nascimento)) problemas.push(`nascimento inválido: "${nascimento}"`);
    else if (pareceVazioOuGenerico(nascimento)) problemas.push('nascimento não coletado');
    if (cpfPareceInvalido(cpf)) problemas.push(`CPF inválido: "${cpf}"`);
    else if (pareceVazioOuGenerico(cpf)) problemas.push('CPF não coletado');
  }
  return problemas.length ? problemas.join('; ') : nome;
}

const nomeFinal = identificacaoIncompleta
  ? `⚠️ DADOS INCOMPLETOS (ligar no telefone abaixo para confirmar ${camposFaltando}) — (${descreveProblema()})`
  : nome;

// ─────────────────────────────────────────
// VALIDAÇÃO DE CONTAMINAÇÃO EM exames_solicitados (Múltiplos exames)
// "Consulta médica" e "ECG" nunca deveriam entrar nessa lista — se entrarem,
// é sinal de que o paciente escolheu números do menu que não são exames de verdade.
// ─────────────────────────────────────────
if (normaliza(servico).includes('multiplos exames')) {
  const contaminado = normaliza(exames_solicitados).includes('consulta');
  if (contaminado) {
    exames_solicitados_final = '⚠️ CONFERIR (lista pode incluir Consulta médica por engano — Consulta não é um exame) — ' + exames_solicitados;
  }
}

return [{
  nome: nomeFinal,
  nascimento,
  cpf,
  servico,
  medico,
  convenio,
  email,
  preferencia,
  telefone: ($('SEPARA MENSAGENS').item.json.telefone || '').split('@')[0],
  tipo_solicitacao,
  data_consulta_atual,
  nova_data_pretendida,
  exames_solicitados: exames_solicitados_final
}];

const primeiro = $input.first()?.json;
const encontrou = !!(primeiro && primeiro.id !== undefined && primeiro.id !== null);
