function montaListaNumerada(cabecalho, listaJson, rodape) {
  try {
    const lista = JSON.parse(listaJson);
    if (!Array.isArray(lista) || lista.length === 0) return null;
    let texto = cabecalho + '\n';
    lista.forEach((item, i) => { texto += `${i + 1}. ${item}\n`; });
    if (rodape) texto += rodape;
    return texto.trim();
  } catch (e) { return null; }
}

