function extraiListaNumerada(texto) {
  const linhas = texto.split('\n');
  const lista = [];
  linhas.forEach(l => {
    const m = l.match(/^\s*(\d+)\.\s*(.+?)\s*$/);
    if (m) {
      const indice = parseInt(m[1], 10);
      if (indice >= 1) lista[indice - 1] = m[2].trim();
    }
  });
  return lista.filter(x => x !== undefined);
}

