function normalizaTxt(v) {
  return (v || '').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
}
function ehPergunta(txt) {
  if (!txt) return false;
  if (txt.trim().endsWith('?')) return true;
  const norm = normalizaTxt(txt);
  const inicios = ['qual', 'quais', 'quando', 'onde', 'quanto', 'quanta', 'quantos', 'quantas',
    'como ', 'quem ', 'tem ', 'existe', 'que horas', 'por que', 'porque', 'pq ',
    'vcs tem', 'voces tem', 'aceita', 'atende', 'posso ', 'pode ', 'preciso saber'];
  return inicios.some(p => norm.startsWith(p));
}

