  return texto;
}

// Monta o bloco [ENVIAR_RECEPCAO] a partir de um objeto de fechamento —
// reaproveitado tanto pelo pré-agendamento quanto por Múltiplos Exames.
// A mensagem de fechamento é SEMPRE a de pré-agendamento (confirmado com
// card e transcript reais — o texto de "vou encaminhar pra recepção
// organizar" não é mais usado neste ponto do fluxo).
function montaBlocoEnviarRecepcao(f) {
  const mensagemFechamento = 'Perfeito! Seu pré-agendamento foi registrado. Em breve nossa recepção entrará em contato para confirmar o horário. Qualquer dúvida é só chamar!';

  return [
    mensagemFechamento,
    '',
    '[ENVIAR_RECEPCAO]',
    `nome: ${f.nome}`,
    `nascimento: ${f.nascimento}`,
    `cpf: ${f.cpf}`,
    'tipo: novo',
    `servico: ${f.servico}`,
    `medico: ${f.medico}`,
    `convenio: ${f.convenio}`,
    `preferencia: ${f.preferencia}`,
    `exames_solicitados: ${f.exames_solicitados}`,
    `telefone: ${f.telefone}`,
    '[FIM_RESUMO]'
  ].join('\n');
}

// ─────────────────────────────────────────
// MÉDICOS VÁLIDOS POR EXAME — mesmas 4 listas de texto acima, mapeadas por
// nome de exame, pra montar a pergunta "médico de cada exame" dinamicamente
// conforme a fila de pendentes (que pode ter só alguns exames, na segunda
// rodada de uma resposta parcial).
// ─────────────────────────────────────────
const MEDICOS_POR_EXAME_TEXTO = {
  [normaliza('Consulta médica')]: [
    'Dr. Amberson Vieira de Assis', 'Dr. Cesar Paleari', 'Dra. Fabiana Impaléa Paleari',
    'Dr. Ilnei Pereira Filho', 'Dr. José Antonio Carvalho', 'Dr. Leonardo Guillermo Cal',
    'Dr. Marcos Ferranti Smaniotto', 'Dra. Sheila Montano Veja'
  ],
  [normaliza('ECG - Eletrocardiograma')]: [
    'Dr. Amberson Vieira de Assis', 'Dr. Cesar Paleari', 'Dra. Fabiana Impaléa Paleari',
    'Dr. Ilnei Pereira Filho', 'Dr. José Antonio Carvalho', 'Dr. Leonardo Guillermo Cal',
    'Dr. Marcos Ferranti Smaniotto'
  ],
  [normaliza('MAPA 24 horas')]: [
    'Dr. Amberson Vieira de Assis', 'Dr. Cesar Paleari', 'Dra. Fabiana Impaléa Paleari',
    'Dr. Ilnei Pereira Filho', 'Dr. José Antonio Carvalho', 'Dr. Leonardo Guillermo Cal',
    'Dr. Marcos Ferranti Smaniotto'
  ],
  [normaliza('Holter 24 horas')]: [
    'Dr. Amberson Vieira de Assis', 'Dr. Cesar Paleari', 'Dra. Fabiana Impaléa Paleari',
    'Dr. Ilnei Pereira Filho', 'Dr. José Antonio Carvalho', 'Dr. Leonardo Guillermo Cal',
    'Dr. Marcos Ferranti Smaniotto'
  ],
  [normaliza('Teste Ergométrico Computadorizado')]: [
    'Dr. Cesar Paleari', 'Dra. Fabiana Impaléa Paleari', 'Dr. Ilnei Pereira Filho',
    'Dr. José Antonio Carvalho', 'Dr. Leonardo Guillermo Cal', 'Dr. Marcos Ferranti Smaniotto'
  ],
  [normaliza('Ecocardiograma Doppler Transtorácico')]: [
    'Dr. José Antonio Carvalho', 'Dr. Leonardo Guillermo Cal'
  ],
  [normaliza('Ecocardiograma Doppler de Carótidas e Vertebrais')]: [
    'Dr. José Antonio Carvalho', 'Dr. Leonardo Guillermo Cal'
  ]
};

// Monta a pergunta de médico por exame, só pros exames que ainda estão
// pendentes — CORRIGIDO (31/jul, após teste real): em vez de UMA mensagem
// gigante com todos os exames juntos, devolve um ARRAY de mensagens (uma
// linha de instrução + um bloco por exame), pra cada uma virar uma mensagem
// separada de WhatsApp via |||. Isso é a mesma mitigação já documentada no
// projeto pro bug conhecido de truncamento de mensagens longas — a pergunta
// de 4 exames com listas de médico virou, sem querer, a mensagem mais longa
// do sistema inteiro.
function montaMensagensMedicosPendentes(examesPendentes) {
  const mensagens = [];
  mensagens.push('Escolha o médico de cada exame — responda com o nome do médico (ou "sem preferência"), na mesma ordem dos exames abaixo, separados por vírgula:');
  examesPendentes.forEach((exame, i) => {
    const medicos = MEDICOS_POR_EXAME_TEXTO[normaliza(exame)] || [];
    let bloco = `${i + 1}. ${exame} — escolha um destes médicos (ou "sem preferência"):\n`;
    bloco += medicos.join('\n');
    mensagens.push(bloco);
  });
  return mensagens;
}

let partes = [];

// ── 0) NOME / NASCIMENTO CAPTURADOS (restaurado 03/ago) ──
// Avança pra próxima pergunta sem a IA "julgar" se o texto parece um nome
// válido — corrige o caso real de nomes confundidos com exames ("Holtz ecos"
// lido como Holter + Eco; "Hults" lido como Holter 24h).
//
// O CPF NÃO entra aqui de propósito: a pergunta seguinte ao CPF depende do
// caminho escolhido no menu inicial (Consulta vs Exame), informação que a
// máquina não rastreia — forçar uma resposta fixa aí quebrou o fluxo da
// Consulta em 01/ago. Depois do CPF, quem decide continua sendo a IA.
if (d.nomeCapturado) {
  // Nome só é capturado FORA de cancelamento/remarcação (revert 04/ago), então
  // aqui a próxima pergunta é sempre a de nascimento (pré-agendamento).
  partes.push('Qual sua data de nascimento?');
}
else if (d.nascimentoCapturado) {
  partes.push('Qual o seu CPF?');
}
// ── 0.4) DADO INVÁLIDO (NOVO, 03/ago à noite) — repete a pergunta com a
// mensagem de erro, deterministicamente (validação do bug #51, agora em
// código, já que o bypass pula a IA nessas etapas). A etapa salva não muda
// (a mensagem de erro não bate em nenhum detector do DETECTA ETAPA, e o
// COALESCE preserva a etapa anterior) — então a próxima resposta do
// paciente é validada de novo, quantas vezes precisar.
else if (d.nomeInvalido) {
    partes.push(
        'Não consegui identificar seu nome. Pode me informar seu nome completo, por favor?'
    );
}
else if (d.nascimentoInvalido) {
  partes.push('Não consegui entender a data. Por favor, informe sua data de nascimento apenas com números, no formato dia/mês/ano. Exemplo: 05/03/1980');
}
else if (d.cpfInvalido) {
  partes.push('O CPF precisa ter 11 números, sem letras. Pode me informar novamente, por favor? Exemplo: 12345678900');
}
// ── 0.5) APÓS O CPF (NOVO, 03/ago) — os dois caminhos, determinísticos ──
// Consulta (opção 1 no menu inicial) -> pergunta de exame no mesmo dia.
// Exame (opção 2) -> marcador [LISTA_SERVICOS] (o SEPARA MENSAGENS troca o
// marcador pela lista completa, igual faz com a resposta da IA).
// Assim a IA não precisa retomar o fluxo depois do CPF — era aí que ela
// repetia a pergunta do nome, por não ter as trocas bypassadas na memória.
else if (d.cpfCapturadoConsulta) {
  partes.push('Tem algum exame para fazer no mesmo dia da consulta? Responda com o(s) número(s), separados por vírgula, ou 0 se não:\n1. Teste Ergométrico Computadorizado\n2. Ecocardiograma Doppler Transtorácico\n3. Eco Doppler de Carótidas e Vertebrais\n4. Holter de Arritmia (24 horas)\n5. MAPA (Holter de pressão)\n6. ECG - Eletrocardiograma\n0. Nenhum exame');
}
else if (d.cpfCapturadoExame) {
  partes.push('[LISTA_SERVICOS]');
}

// ── 1) EXAME NO MESMO DIA CONFIRMADO ──
else if (d.exameConfirmadoDeterministico) {
  if (d.exameConfirmadoDeterministico !== 'Nenhum') {
    d.exameConfirmadoDeterministico.split(', ').forEach(e => partes.push(`Anotado, ${e} incluído.`));
  }
  partes.push(LISTA_MEDICOS_CONSULTA);
}

// ── 2) SERVIÇO CONFIRMADO (PASSO 4) ──
else if (d.servicoConfirmadoDeterministico) {
  const s = d.servicoConfirmadoDeterministico;
  if (s === 'ECG - Eletrocardiograma') {
    partes.push(MENSAGEM_OFICIAL_ECG);
  } else if (s === 'Consulta médica') {
    partes.push('Tem algum exame para fazer no mesmo dia da consulta? Responda com o(s) número(s), separados por vírgula, ou 0 se não:\n1. Teste Ergométrico Computadorizado\n2. Ecocardiograma Doppler Transtorácico\n3. Eco Doppler de Carótidas e Vertebrais\n4. Holter de Arritmia (24 horas)\n5. MAPA (Holter de pressão)\n0. Nenhum exame');
  } else if (s === 'Teste Ergométrico Computadorizado') {
    partes.push(LISTA_MEDICOS_ERGOMETRICO);
  } else if (s === 'Ecocardiograma Doppler Transtorácico') {
    partes.push(LISTA_MEDICOS_ECO);
  } else if (s === 'Ecocardiograma Doppler de Carótidas e Vertebrais') {
    partes.push('Você precisa da Eco de Carótidas Interna, Externa, ou as duas (Interna e Externa)? Responda com o número:\n1. Interna\n2. Externa\n3. As duas (Interna e Externa)');
  } else if (s === 'MAPA 24 horas' || s === 'Holter 24 horas') {
    partes.push(LISTA_MEDICOS_ECG_MAPA_HOLTER);
  }
}

// ── 2.6) MÚLTIPLOS EXAMES — SELEÇÃO CONFIRMADA (entrada no fluxo) ──
// Nome/nascimento/CPF SEMPRE já estão coletados neste ponto (PASSOS 1-3
// vêm antes do PASSO 4 na sequência fixa do prompt) — não precisa checar.
// Vai direto pra pergunta de médico de cada exame.
else if (d.multiplosExamesAtivo && d.examesMultiplosSelecionados) {
  partes.push(`Você escolheu: ${d.examesMultiplosSelecionados}.`);
  const pendentes = JSON.parse(d.medicosMultiplosPendentesAtualizado || '[]');
  montaMensagensMedicosPendentes(pendentes).forEach(m => partes.push(m));
}

// ── 2.7) MÚLTIPLOS EXAMES — MÉDICO(S) RESOLVIDO(S) (NOVO, 31/jul à noite) ──
else if (d.medicosMultiplosResolvidosAtualizado) {
  if (d.medicosMultiplosCompleto) {
    // Todos os exames já têm médico — próxima e última pergunta: convênio.
    partes.push('O atendimento será por convênio ou particular? Responda com o número:\n1. Convênio\n2. Particular');
  } else {
    // Resposta parcial — reformula a pergunta só com os exames que sobraram.
    const pendentes = JSON.parse(d.medicosMultiplosPendentesAtualizado || '[]');
    montaMensagensMedicosPendentes(pendentes).forEach(m => partes.push(m));
  }
}

// ── 2.5) TIPO DE CARÓTIDAS CONFIRMADO (Interna / Externa / Ambos) ──
else if (d.carotidasTipoConfirmado) {
  if (d.carotidasTipoConfirmado === 'interna') {
    partes.push('Preferência de médico? Responda com número ou diga sem preferência:\n1. Dr. José Antonio Carvalho (Cardiologista)\n2. Dr. Leonardo Guillermo Cal (Cardiologista/Pediátrico)');
  } else {
    partes.push('Preferência de médico? Responda com número ou diga sem preferência:\n1. Dr. Leonardo Guillermo Cal (Cardiologista/Pediátrico)');
  }
}

// ── 3) MÉDICO CONFIRMADO ──
else if (d.medicoConfirmadoDeterministico) {
  partes.push(`Você escolheu: ${d.medicoConfirmadoDeterministico.replace(/\s*\(.*?\)\s*$/, '')}.`);
  if (d.politicaMedicoResolvido === 'somente_particular') {
    partes.push('Esse médico atende somente particular.');
    partes.push('Você possui algum cartão de desconto? Responda com o número:\n1. Saudesc\n2. CDL AEMFLO\n3. Não tenho');
  } else {
    partes.push('O atendimento será por convênio ou particular? Responda com o número:\n1. Convênio\n2. Particular');
  }
}

// ── 4) CONVÊNIO OU PARTICULAR CONFIRMADO ──
else if (d.convenioOuParticularDeterministico) {
  if (d.convenioOuParticularDeterministico === 'particular') {
    partes.push('Você possui algum cartão de desconto? Responda com o número:\n1. Saudesc\n2. CDL AEMFLO\n3. Não tenho');
  } else {
    const medicoSalvo = $('BUSCA ESTADO CONVERSA').item.json.medico_escolhido || '';
    const nomeSemParenteses = medicoSalvo.replace(/\(.*?\)/g, '').trim();
    const excetoUnimed = normaliza(nomeSemParenteses).includes(normaliza('Dr. Marcos Ferranti Smaniotto'));
    if (excetoUnimed) {
      partes.push('Qual convênio? Responda com o número:\n1. ASSEFAZ\n2. GEAP\n3. Saúde Caixa\n4. Postal Saúde\n5. SCSaúde\n6. EloSaúde');
    } else {
      partes.push('Qual convênio? Responda com o número:\n1. ASSEFAZ\n2. GEAP\n3. Saúde Caixa\n4. Postal Saúde\n5. Unimed\n6. SCSaúde\n7. EloSaúde');
    }
  }
}

// ── 5) QUAL CONVÊNIO CONFIRMADO ──
// Se for Múltiplos Exames com médicos já resolvidos, fecha direto (sem
// dia/período). Caso contrário, segue o fluxo normal de pré-agendamento.
else if (d.qualConvenioDeterministico) {
  if (d.fechamentoMultiplosExames) {
    partes.push(montaBlocoEnviarRecepcao(JSON.parse(d.fechamentoMultiplosExames)));
  } else {
    const medicoSalvo = $('BUSCA ESTADO CONVERSA').item.json.medico_escolhido || '';
    partes.push(montaListaDiaPeriodo(medicoSalvo));
  }
}

// ── 6) CARTÃO DE DESCONTO CONFIRMADO ──
// Mesma lógica do item 5: fecha direto se for Múltiplos Exames completo.
else if (d.cartaoDescontoDeterministico) {
  if (d.fechamentoMultiplosExames) {
    partes.push(montaBlocoEnviarRecepcao(JSON.parse(d.fechamentoMultiplosExames)));
  } else {
    const medicoSalvo = $('BUSCA ESTADO CONVERSA').item.json.medico_escolhido || '';
    partes.push(montaListaDiaPeriodo(medicoSalvo));
  }
}

// ── 7) FECHAMENTO COMPLETO — PRÉ-AGENDAMENTO (dia/período respondido E já temos todos os dados) ──
else if (d.fechamentoDeterministico) {
  const f = JSON.parse(d.fechamentoDeterministico);
  partes.push(montaBlocoEnviarRecepcao(f));
}

return [{
  output: partes.join('|||')
}];

// Node: DETECTA RESPOSTA DETERMINISTICA
// Substitui o node "DETECTA RESPOSTA EXAMES MESMO DIA" (faz o mesmo, e mais).
// Posição: logo depois de "BUSCA ESTADO CONVERSA", antes de "FORMATA ETAPA PARA PROMPT".
//
// REESCRITO 31/jul à noite — a versão anterior desta extensão presumia
// medico/convenio fixos em "A definir pela recepção" pra Múltiplos Exames.
// Confirmado com transcript e card reais que o fluxo verdadeiro é:
// exames -> MÉDICO POR EXAME (texto livre, resposta parcial permitida) ->
// convênio/particular (compartilhado) -> fecha (sem dia/período).
// Interruptor MULTIPLOS_EXAMES_BYPASS_ATIVO permanece como rede de segurança,
// agora LIGADO — testado e revisado antes de reativar.

const MULTIPLOS_EXAMES_BYPASS_ATIVO = true;

const estado = $('BUSCA ESTADO CONVERSA').item.json;
const etapaAnterior = estado.etapa_atual;
const mensagemPaciente = ($('AGRUPA MENSAGENS').item.json.concatenated_content || '').trim();
const telefone = ($('Coleta').item.json.telefone || '').split('@')[0];
const sessionKey = telefone + '_' + $now.toFormat('yyyyMMdd');

const respostaSoNumeros = /^[\d,\s]+$/.test(mensagemPaciente) && mensagemPaciente !== '';
const respostaUmNumero = /^\d+$/.test(mensagemPaciente);

// Política de convênio de cada médico — usada depois de resolver o médico,
// para saber se pula direto pro cartão de desconto ou pergunta convênio.
function normaliza(v) {
  return (v || '').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
}
const POLITICA_CONVENIO = {
  [normaliza('Dr. Amberson Vieira de Assis')]: 'somente_particular',
  [normaliza('Dra. Sheila Montano Veja')]: 'somente_particular',
  [normaliza('Dr. Marcos Ferranti Smaniotto')]: 'todos_exceto_unimed'
  // Qualquer médico não listado aqui = 'todos_os_convenios' (padrão).
};
function politicaDoMedico(nomeCompleto) {
  // O nome vem com "(Cardiologista)" etc. junto — comparamos só pelo nome, ignorando o parêntese.
  const nomeSemParenteses = (nomeCompleto || '').replace(/\(.*?\)/g, '').trim();
  for (const chave in POLITICA_CONVENIO) {
    if (normaliza(nomeSemParenteses).includes(chave)) return POLITICA_CONVENIO[chave];
  }
  return 'todos_os_convenios';
}

// ─────────────────────────────────────────
// MÉDICOS VÁLIDOS POR EXAME (mesmas 8 pessoas, subconjuntos diferentes por
// exame — igual às 4 listas já usadas em GERA_RESPOSTA_DETERMINISTICA.js).
// Matching por PRIMEIRO NOME normalizado: os 8 primeiros nomes são únicos
// entre si, então isso nunca gera ambiguidade real.
// ─────────────────────────────────────────
const MEDICOS_TODOS = [
  { chave: 'amberson', nome: 'Dr. Amberson Vieira de Assis' },
  { chave: 'cesar', nome: 'Dr. Cesar Paleari' },
  { chave: 'fabiana', nome: 'Dra. Fabiana Impaléa Paleari' },
  { chave: 'ilnei', nome: 'Dr. Ilnei Pereira Filho' },
  { chave: 'jose', nome: 'Dr. José Antonio Carvalho' },
  { chave: 'leonardo', nome: 'Dr. Leonardo Guillermo Cal' },
  { chave: 'marcos', nome: 'Dr. Marcos Ferranti Smaniotto' },
  { chave: 'sheila', nome: 'Dra. Sheila Montano Veja' }
];
const CHAVES_POR_EXAME = {
  [normaliza('Consulta médica')]: ['amberson', 'cesar', 'fabiana', 'ilnei', 'jose', 'leonardo', 'marcos', 'sheila'],
  [normaliza('ECG - Eletrocardiograma')]: ['amberson', 'cesar', 'fabiana', 'ilnei', 'jose', 'leonardo', 'marcos'],
  [normaliza('MAPA 24 horas')]: ['amberson', 'cesar', 'fabiana', 'ilnei', 'jose', 'leonardo', 'marcos'],
  [normaliza('Holter 24 horas')]: ['amberson', 'cesar', 'fabiana', 'ilnei', 'jose', 'leonardo', 'marcos'],
  [normaliza('Teste Ergométrico Computadorizado')]: ['cesar', 'fabiana', 'ilnei', 'jose', 'leonardo', 'marcos'],
  [normaliza('Ecocardiograma Doppler Transtorácico')]: ['jose', 'leonardo'],
  [normaliza('Ecocardiograma Doppler de Carótidas e Vertebrais')]: ['jose', 'leonardo']
};
const VARIACOES_SEM_PREFERENCIA = ['sem preferencia', 'qualquer', 'tanto faz', 'indiferente', 'nao tenho preferencia'];

// Resolve UMA resposta de médico pra UM exame específico. Retorna o nome
// canônico do médico, 'sem preferência', ou null (não reconheceu / ambíguo —
// null é o sinal pra parar tudo e deixar a IA decidir, por segurança).
function resolveMedicoResposta(respostaBruta, chavesPermitidas) {
  const norm = normaliza(respostaBruta);
  if (!norm || !chavesPermitidas) return null;

  if (VARIACOES_SEM_PREFERENCIA.some(v => norm === v || norm.includes(v))) {
    return 'sem preferência';
  }

  const candidatos = MEDICOS_TODOS.filter(m => chavesPermitidas.includes(m.chave) && norm.includes(m.chave));
  return candidatos.length === 1 ? candidatos[0].nome : null;
}

let resultado = {
  exameConfirmadoDeterministico: null,
  servicoConfirmadoDeterministico: null,
  medicoConfirmadoDeterministico: null,
  convenioOuParticularDeterministico: null,
  qualConvenioDeterministico: null,
  cartaoDescontoDeterministico: null,
  diaPeriodoDeterministico: null,
  politicaMedicoResolvido: null // usado pelo GERA RESPOSTA pra saber a próxima pergunta
};

// 1) EXAMES NO MESMO DIA
const MAPA_EXAMES_MESMO_DIA = {
  '1': 'Teste Ergométrico Computadorizado',
  '2': 'Ecocardiograma Doppler Transtorácico',
  '3': 'Eco Doppler de Carótidas e Vertebrais',
  '4': 'Holter de Arritmia (24 horas)',
  '5': 'MAPA (Holter de pressão)',
  '6': 'ECG - Eletrocardiograma'
};
if (etapaAnterior === 'aguardando_exames_mesmo_dia' && respostaSoNumeros) {
  const numeros = mensagemPaciente.split(',').map(n => n.trim()).filter(n => n !== '');
  if (numeros.includes('0')) {
    resultado.exameConfirmadoDeterministico = 'Nenhum';
  } else {
    const nomes = numeros.map(n => MAPA_EXAMES_MESMO_DIA[n]).filter(Boolean);
    if (nomes.length > 0) resultado.exameConfirmadoDeterministico = nomes.join(', ');
  }
}

// 1.9) OPÇÃO DO MENU INICIAL (NOVO, 03/ago) — captura de forma determinística
// se o paciente escolheu 1 (Consulta) ou 2 (Exame) no primeiro menu. É essa
// informação que decide qual pergunta vem depois do CPF:
//   Consulta -> "Tem algum exame para fazer no mesmo dia da consulta?"
//   Exame    -> [LISTA_SERVICOS]
// Sem isso, a decisão voltava pra IA — que erra, porque as trocas bypassadas
// (nome, nascimento) não entram no Simple Memory dela, e ela acha que ainda
// está esperando o nome. Foi a causa do loop de 03/ago.
resultado.opcaoInicialConsulta = false;
if (etapaAnterior === 'aguardando_opcao_inicial' && mensagemPaciente.trim() === '1') {
  resultado.opcaoInicialConsulta = true;
}

// 2) SERVIÇO (PASSO 4) — seleção de UM item só
const MAPA_SERVICO = {
  '1': 'Consulta médica',
  '2': 'ECG - Eletrocardiograma',
  '3': 'Teste Ergométrico Computadorizado',
  '4': 'Ecocardiograma Doppler Transtorácico',
  '5': 'Ecocardiograma Doppler de Carótidas e Vertebrais',
  '6': 'MAPA 24 horas',
  '7': 'Holter 24 horas'
};
if (etapaAnterior === 'aguardando_servico' && respostaUmNumero && MAPA_SERVICO[mensagemPaciente]) {
  resultado.servicoConfirmadoDeterministico = MAPA_SERVICO[mensagemPaciente];
}

// 2.6) MÚLTIPLOS EXAMES — detecção de ENTRADA no fluxo. Mesma etapa
// 'aguardando_servico' do item 2, mas com 2+ números. Reaproveita o MESMO
// MAPA_SERVICO já validado. Também inicializa a fila de médicos pendentes
// (mesma ordem dos exames escolhidos) — é essa fila que a próxima pergunta
// (médico de cada exame) vai usar e ir reduzindo.
resultado.examesMultiplosSelecionados = null;
resultado.multiplosExamesAtivo = false;
resultado.medicosMultiplosPendentesAtualizado = null;
resultado.medicosMultiplosResolvidosAtualizado = null;
resultado.medicosMultiplosCompleto = false;

if (MULTIPLOS_EXAMES_BYPASS_ATIVO && etapaAnterior === 'aguardando_servico' && respostaSoNumeros) {
  const numeros = mensagemPaciente.split(',').map(n => n.trim()).filter(n => n !== '');
  const numerosUnicos = [...new Set(numeros)];
  if (numerosUnicos.length >= 2) {
    const nomes = numerosUnicos.map(n => MAPA_SERVICO[n]).filter(Boolean);
    // Só ativa o fluxo se TODOS os números escolhidos forem válidos — número
    // inválido misturado no meio cai pra IA decidir (mais seguro que fechar
    // incompleto ou com exame errado).
    if (nomes.length === numerosUnicos.length && nomes.length >= 2) {
      resultado.examesMultiplosSelecionados = nomes.join(', ');
      resultado.multiplosExamesAtivo = true;
      resultado.medicosMultiplosPendentesAtualizado = JSON.stringify(nomes);
      resultado.medicosMultiplosResolvidosAtualizado = ''; // começa vazio, some por semNull mesmo assim
    }
  }
}

// 2.7) MÚLTIPLOS EXAMES — RESPOSTA DE MÉDICO POR EXAME (NOVO, 31/jul à noite)
// Paciente responde com nomes separados por vírgula, na ordem dos exames
// AINDA PENDENTES (não necessariamente todos). Cada nome é validado contra a
// lista de médicos daquele exame específico. Regra de segurança confirmada
// com o usuário: se QUALQUER nome dado não for reconhecido com confiança
// (ambíguo, fora da lista daquele exame, etc.), NADA é aplicado — a
// mensagem inteira cai pra IA decidir, sem aplicação parcial arriscada.
if (MULTIPLOS_EXAMES_BYPASS_ATIVO && etapaAnterior === 'aguardando_medicos_multiplos' && estado.medicos_multiplos_pendentes && mensagemPaciente) {
  let pendentesAtuais = null;
  try {
    pendentesAtuais = JSON.parse(estado.medicos_multiplos_pendentes);
  } catch (e) { /* deixa null, cai pra IA */ }

  if (Array.isArray(pendentesAtuais) && pendentesAtuais.length > 0) {
    const respostas = mensagemPaciente.split(',').map(r => r.trim()).filter(r => r !== '');

    if (respostas.length > 0 && respostas.length <= pendentesAtuais.length) {
      const paresResolvidos = [];
      let todasValidas = true;

      for (let i = 0; i < respostas.length; i++) {
        const exame = pendentesAtuais[i];
        const chavesPermitidas = CHAVES_POR_EXAME[normaliza(exame)];
        const medicoResolvido = chavesPermitidas ? resolveMedicoResposta(respostas[i], chavesPermitidas) : null;
        if (!medicoResolvido) { todasValidas = false; break; }
        paresResolvidos.push(`${exame}: ${medicoResolvido}`);
      }

      if (todasValidas) {
        const resolvidosAnteriores = estado.medicos_multiplos_resolvidos || '';
        const resolvidosNovos = paresResolvidos.join('; ');
        resultado.medicosMultiplosResolvidosAtualizado = resolvidosAnteriores
          ? `${resolvidosAnteriores}; ${resolvidosNovos}`
          : resolvidosNovos;

        const pendentesRestantes = pendentesAtuais.slice(respostas.length);
        resultado.medicosMultiplosPendentesAtualizado = JSON.stringify(pendentesRestantes);
        resultado.medicosMultiplosCompleto = pendentesRestantes.length === 0;
      }
      // Se todasValidas ficou false, os campos ficam null (setados acima) —
      // nada é salvo, a mensagem cai inteira pra IA.
    }
    // Se vieram MAIS respostas do que exames pendentes, também cai pra IA
    // (não é o padrão esperado — mais seguro não tentar adivinhar o motivo).
  }
}

// 2.5) TIPO DE ECO CARÓTIDAS (Interna / Externa / Ambos) — pergunta extra
// específica desse exame, antes de mostrar o médico. A lista de médico que
// aparece depois muda conforme a resposta (José só faz Interna; Leonardo faz as duas).
if (etapaAnterior === 'aguardando_carotidas_tipo' && respostaUmNumero) {
  if (mensagemPaciente === '1') {
    resultado.carotidasTipoConfirmado = 'interna';
  } else if (mensagemPaciente === '2' || mensagemPaciente === '3') {
    resultado.carotidasTipoConfirmado = 'externa_ou_ambos';
  }
}

// 3) MÉDICO — usa a lista REAL que foi mostrada (guardada pelo DETECTA ETAPA)
if (etapaAnterior === 'aguardando_medico' && respostaUmNumero && estado.medicos_lista_atual) {
  try {
    const lista = JSON.parse(estado.medicos_lista_atual);
    const idx = parseInt(mensagemPaciente, 10) - 1;
    if (lista[idx]) {
      resultado.medicoConfirmadoDeterministico = lista[idx];
      resultado.politicaMedicoResolvido = politicaDoMedico(lista[idx]);
    }
  } catch (e) { /* lista inválida, deixa a IA decidir */ }
}

// 4) CONVÊNIO OU PARTICULAR
if (etapaAnterior === 'aguardando_convenio_ou_particular' && respostaUmNumero) {
  if (mensagemPaciente === '1') resultado.convenioOuParticularDeterministico = 'convenio';
  else if (mensagemPaciente === '2') resultado.convenioOuParticularDeterministico = 'particular';
}

// 5) QUAL CONVÊNIO — usa a lista REAL mostrada
if (etapaAnterior === 'aguardando_qual_convenio' && respostaUmNumero && estado.convenios_lista_atual) {
  try {
    const lista = JSON.parse(estado.convenios_lista_atual);
    const idx = parseInt(mensagemPaciente, 10) - 1;
    if (lista[idx]) resultado.qualConvenioDeterministico = lista[idx];
  } catch (e) {}
}

// 6) CARTÃO DE DESCONTO
const MAPA_CARTAO = {
  '1': 'Particular (Saudesc)',
  '2': 'Particular (CDL AEMFLO)',
  '3': 'Particular'
};
if (etapaAnterior === 'aguardando_cartao_desconto' && respostaUmNumero && MAPA_CARTAO[mensagemPaciente]) {
  resultado.cartaoDescontoDeterministico = MAPA_CARTAO[mensagemPaciente];
}

// 6.5) FECHAMENTO — MÚLTIPLOS EXAMES (NOVO, 31/jul à noite, substitui a
// versão anterior errada). Dispara na MESMA mensagem que resolveu convênio
// (bloco 5) ou cartão de desconto (bloco 6), SE a conversa está no fluxo
// de Múltiplos Exames E todos os médicos já foram resolvidos antes disso.
// Sem pergunta de dia/período neste fluxo — fecha direto daqui.
resultado.fechamentoMultiplosExames = null;
if (MULTIPLOS_EXAMES_BYPASS_ATIVO && estado.multiplos_exames_ativo) {
  const convenioResolvidoAgora = resultado.qualConvenioDeterministico || resultado.cartaoDescontoDeterministico;
  const medicosPendentesVazios = !estado.medicos_multiplos_pendentes || estado.medicos_multiplos_pendentes === '[]';

  if (convenioResolvidoAgora && medicosPendentesVazios && estado.medicos_multiplos_resolvidos
      && estado.nome_coletado && estado.nascimento_coletado && estado.cpf_coletado
      && estado.exames_multiplos_selecionados) {
    resultado.fechamentoMultiplosExames = {
      nome: estado.nome_coletado,
      nascimento: estado.nascimento_coletado,
      cpf: estado.cpf_coletado,
      servico: 'Múltiplos exames',
      medico: estado.medicos_multiplos_resolvidos, // formato "Exame: Médico; Exame: Médico" — confirmado no index.html real
      convenio: convenioResolvidoAgora,
      preferencia: '', // este fluxo não tem dia/período; o card não exibe este campo pra Múltiplos exames
      exames_solicitados: estado.exames_multiplos_selecionados,
      telefone: telefone
    };
  }
}

// 7) DIA E PERÍODO — usa a lista REAL mostrada. "0" = Sem preferência.
if (etapaAnterior === 'aguardando_dia_periodo' && respostaSoNumeros) {
  if (mensagemPaciente.split(',').map(n => n.trim()).length > 1 || mensagemPaciente.trim() === '0') {
    // Vários números ou "0" = trata como Sem preferência (mesma regra do prompt original).
    resultado.diaPeriodoDeterministico = 'Sem preferência';
  } else if (estado.dias_lista_atual) {
    try {
      const lista = JSON.parse(estado.dias_lista_atual);
      const idx = parseInt(mensagemPaciente, 10) - 1;
      if (lista[idx]) resultado.diaPeriodoDeterministico = lista[idx];
    } catch (e) {}
  }
}

// 8) CAPTURA DE NOME/NASCIMENTO/CPF — REESCRITO 03/ago (noite), correções A e B:
//
// A) Só captura quando o fluxo NÃO é cancelamento/remarcação. Nesses fluxos a
//    máquina não cobre a sequência inteira (data a alterar / nova data são
//    texto livre sem bypass), então bypassar só o nome criava buraco no
//    Simple Memory da IA e loop nome<->data (testes 5, 6 e 7 de 03/ago).
//    Princípio da seção 27 do resumo: ou a sequência inteira é determinística,
//    ou não se bypassa nenhum ponto no meio dela. Em cancelamento/remarcação,
//    tudo volta pra IA — como era na bateria de 01/ago, que funcionou.
//    IMPORTANTE: fluxo null NÃO bloqueia (conversa recém-iniciada ou logo
//    após reset de nova pessoa) — só bloqueia 'cancelamento_remarcacao'
//    explícito. Isso preserva os cenários de 2 pessoas que já funcionam.
//
// B) Se o texto parecer uma PERGUNTA do paciente (termina em "?" ou começa
//    com palavra interrogativa), NÃO captura — cai pra IA, que responde e
//    retoma a etapa (o FORMATA ETAPA PARA PROMPT já injeta a etapa correta
//    mecanicamente no systemMessage, então a retomada não depende da memória
//    furada). Corrige o teste 4 ("Tem estacionamento?" virou nome; "qual
//    horario de atendimento?" virou CPF).
//
// B2) Validação de formato EM CÓDIGO (regra do bug #51, que estava no prompt
//    e parou de rodar quando o bypass passou a pular a IA nessas etapas):
//    - nascimento: sem letras, 6 a 8 dígitos (aceita com/sem barras)
//    - CPF: sem letras, exatamente 11 dígitos
//    Inválido -> repete a pergunta com mensagem de erro, deterministicamente
//    (campos nascimentoInvalido/cpfInvalido, tratados no GERA RESPOSTA).
function pareceUmaPergunta(txt) {
  if (!txt) return false;
  if (txt.trim().endsWith('?')) return true;
  const norm = normaliza(txt);
  const inicios = ['qual', 'quais', 'quando', 'onde', 'quanto', 'quanta', 'quantos', 'quantas',
    'como ', 'quem ', 'tem ', 'existe', 'que horas', 'por que', 'porque', 'pq ',
    'vcs tem', 'voces tem', 'aceita', 'atende', 'posso ', 'pode ', 'preciso saber'];
  return inicios.some(p => norm.startsWith(p));
}

// CORREÇÃO A REFINADA (04/ago): a versão de 03/ago bloqueava TODA a
// identificação (nome, nascimento, CPF) em cancelamento/remarcação, pra
// parar o loop nome<->data. Mas nesses fluxos SÓ existe o nome como
// identificação (depois vem data, que é texto livre da IA) — e capturar o
// NOME nunca criou o loop (o loop era da data). Bloquear o nome só devolveu
// pra IA o problema de nome estranho não ser aceito (testes 2 e 4 de 04/ago:
// "Holts eccos"/"Holts arritimo" travaram em remarcação/cancelamento).
//
// REVERTIDO (04/ago, tarde): em cancelamento/remarcação, a IA conduz o fluxo
// inteiro (nome -> data atual -> nova data -> card), como funcionava na
// bateria de 01/ago. O bypass de identificação fica DESLIGADO nesses fluxos —
// tanto o determinismo completo quanto o bypass só do nome causaram loop
// nome<->data (a data é texto livre da IA, e o bypass do nome deixava buraco
// na memória dela). Trade-off aceito com o usuário: nome estranho parecido com
// exame pode falhar nesses 2 fluxos (caso raro), em troca de estabilidade.
// Fora de cancelamento/remarcação, tudo continua determinístico como estava.
const ehCancelamentoRemarcacao = (estado.fluxo === 'cancelamento_remarcacao');

resultado.nomeCapturado = null;
resultado.nomeInvalido = false;
resultado.nascimentoCapturado = null;
resultado.cpfCapturado = null;
resultado.nascimentoInvalido = false;
resultado.cpfInvalido = false;

if (!ehCancelamentoRemarcacao && mensagemPaciente && !pareceUmaPergunta(mensagemPaciente)) {
  if (etapaAnterior === 'aguardando_nome') {

    const texto = mensagemPaciente.trim();

    const nomeValido =
    texto.length >= 3 &&
    /[A-Za-zÀ-ÿ]/.test(texto) &&
    !/^\d+$/.test(texto) &&
    !/^[\d\s.,-]+$/.test(texto);

    if (nomeValido) {
        resultado.nomeCapturado = texto;
    } else {
        resultado.nomeInvalido = true;
    }
}
  if (etapaAnterior === 'aguardando_nascimento') {
    const temLetra = /[a-zA-Zà-úÀ-Ú]/.test(mensagemPaciente);
    const qtdDigitos = (mensagemPaciente.match(/\d/g) || []).length;
    if (!temLetra && qtdDigitos >= 6 && qtdDigitos <= 8) {
      resultado.nascimentoCapturado = mensagemPaciente;
    } else {
      resultado.nascimentoInvalido = true;
    }
  }
  if (!ehCancelamentoRemarcacao && etapaAnterior === 'aguardando_cpf') {
    const temLetra = /[a-zA-Zà-úÀ-Ú]/.test(mensagemPaciente);
    const soDigitos = mensagemPaciente.replace(/\D/g, '');
    if (!temLetra && soDigitos.length === 11) {
      resultado.cpfCapturado = mensagemPaciente;
    } else {
      resultado.cpfInvalido = true;
    }
  }
}

// 8.5) CAMINHO APÓS O CPF (NOVO, 03/ago) — agora determinístico nos DOIS
// caminhos, para a IA nunca precisar retomar o fluxo no meio (é aí que ela
// erra, por causa dos buracos que o bypass deixa no Simple Memory dela).
// A flag opcao_inicial_consulta (sticky, salva no banco) diz qual é:
//   true  -> Consulta: próxima pergunta é "exame no mesmo dia?"
//   false -> Exame:    próxima pergunta é o [LISTA_SERVICOS]
resultado.cpfCapturadoConsulta = !!(resultado.cpfCapturado && estado.opcao_inicial_consulta);
resultado.cpfCapturadoExame = !!(resultado.cpfCapturado && !estado.opcao_inicial_consulta);


// 9) FECHAMENTO DETERMINÍSTICO — PRÉ-AGENDAMENTO (fluxo normal, 1 serviço só).
// Só dispara quando a resposta de AGORA é o dia/período (a última etapa da
// sequência) E já temos TODOS os outros dados guardados na máquina de
// estado. Se qualquer coisa faltar, não fecha aqui — deixa a IA decidir
// normalmente (mais seguro do que fechar com dado incompleto).
resultado.fechamentoDeterministico = null;
if (etapaAnterior === 'aguardando_dia_periodo' && resultado.diaPeriodoDeterministico) {
  const servicoFinal = estado.servico_consulta_detectado ? 'Consulta médica' : estado.servico_escolhido;
  const medicoFinal = estado.medico_escolhido ? estado.medico_escolhido.replace(/\s*\(.*?\)\s*$/, '') : null;
  const convenioFinal = estado.qual_convenio_confirmado || estado.cartao_desconto_confirmado || null;

  const temTudo = estado.nome_coletado && estado.nascimento_coletado && estado.cpf_coletado
    && servicoFinal && medicoFinal && convenioFinal;

  if (temTudo) {
    let preferenciaFinal;
    if (resultado.diaPeriodoDeterministico === 'Sem preferência') {
      preferenciaFinal = 'Sem preferência';
    } else {
      const partes = resultado.diaPeriodoDeterministico.split(' - ');
      preferenciaFinal = partes.length === 2 ? `${partes[1]}, ${partes[0]}` : resultado.diaPeriodoDeterministico;
    }

    let examesFinal = '';
    if (normaliza(servicoFinal) === normaliza('Consulta médica')) {
      examesFinal = estado.exames_mesmo_dia_confirmado || 'Nenhum';
    }

    resultado.fechamentoDeterministico = {
      nome: estado.nome_coletado,
      nascimento: estado.nascimento_coletado,
      cpf: estado.cpf_coletado,
      servico: servicoFinal,
      medico: medicoFinal,
      convenio: convenioFinal,
      preferencia: preferenciaFinal,
      exames_solicitados: examesFinal,
      telefone: telefone
    };
  }
}

// ─────────────────────────────────────────
// SANITIZAÇÃO FINAL: troca null por string vazia ('') em todos os campos
// simples, e serializa os objetos de fechamento como texto (JSON) ou '' —
// o IF "is not empty" do n8n às vezes trata null como "não vazio", então
// nunca deixamos null sair daqui, só '' ou um valor real.
// ─────────────────────────────────────────
function semNull(v) {
  return v === null || v === undefined ? '' : v;
}

const saida = {
  exameConfirmadoDeterministico: semNull(resultado.exameConfirmadoDeterministico),
  servicoConfirmadoDeterministico: semNull(resultado.servicoConfirmadoDeterministico),
  medicoConfirmadoDeterministico: semNull(resultado.medicoConfirmadoDeterministico),
  convenioOuParticularDeterministico: semNull(resultado.convenioOuParticularDeterministico),
  qualConvenioDeterministico: semNull(resultado.qualConvenioDeterministico),
  cartaoDescontoDeterministico: semNull(resultado.cartaoDescontoDeterministico),
  diaPeriodoDeterministico: semNull(resultado.diaPeriodoDeterministico),
  politicaMedicoResolvido: semNull(resultado.politicaMedicoResolvido),
  nomeCapturado: semNull(resultado.nomeCapturado),
  nomeInvalido: !!resultado.nomeInvalido,
  nascimentoCapturado: semNull(resultado.nascimentoCapturado),
  cpfCapturado: semNull(resultado.cpfCapturado),
  carotidasTipoConfirmado: semNull(resultado.carotidasTipoConfirmado),
  examesMultiplosSelecionados: semNull(resultado.examesMultiplosSelecionados),
  multiplosExamesAtivo: !!resultado.multiplosExamesAtivo,
  medicosMultiplosPendentesAtualizado: semNull(resultado.medicosMultiplosPendentesAtualizado),
  medicosMultiplosResolvidosAtualizado: semNull(resultado.medicosMultiplosResolvidosAtualizado),
  medicosMultiplosCompleto: !!resultado.medicosMultiplosCompleto,
  fechamentoDeterministico: resultado.fechamentoDeterministico ? JSON.stringify(resultado.fechamentoDeterministico) : '',
  fechamentoMultiplosExames: resultado.fechamentoMultiplosExames ? JSON.stringify(resultado.fechamentoMultiplosExames) : '',
  opcaoInicialConsulta: !!resultado.opcaoInicialConsulta,
  cpfCapturadoConsulta: !!resultado.cpfCapturadoConsulta,
  cpfCapturadoExame: !!resultado.cpfCapturadoExame,
  nascimentoInvalido: !!resultado.nascimentoInvalido,
  cpfInvalido: !!resultado.cpfInvalido
};

const algumaRespostaDeterministica = !!(
  saida.exameConfirmadoDeterministico ||
  saida.servicoConfirmadoDeterministico ||
  saida.medicoConfirmadoDeterministico ||
  saida.convenioOuParticularDeterministico ||
  saida.qualConvenioDeterministico ||
  saida.cartaoDescontoDeterministico ||
  saida.carotidasTipoConfirmado ||
  saida.examesMultiplosSelecionados ||
  saida.medicosMultiplosResolvidosAtualizado ||
  saida.fechamentoDeterministico ||
  saida.fechamentoMultiplosExames ||
  // RESTAURADO (03/ago): nome e nascimento voltam a disparar o bypass. Sem
  // isso, a IA é quem decide se aceita o texto como nome — e ela erra,
  // confundindo nomes com exames (caso real: "Holtz ecos" virou "Holter +
  // Ecocardiograma"; antes disso, "Hults" virou "Holter 24h"). Com o bypass,
  // qualquer texto não vazio é aceito como nome e o fluxo avança sozinho.
  //
  // ATENÇÃO — cpfCapturado NÃO entra aqui de propósito: o que vem DEPOIS do
  // CPF depende de qual opção foi escolhida no menu inicial (1. Consulta ->
  // "exame no mesmo dia?"; 2. Exame -> [LISTA_SERVICOS]), e essa informação
  // a máquina não rastreia. Incluir o CPF aqui quebrou o caminho da Consulta
  // em 01/ago. Só nome e nascimento, que têm próxima pergunta sempre fixa.
  saida.nomeCapturado ||
  saida.nomeInvalido ||
  saida.nascimentoCapturado ||
  // CPF entra no gatilho (03/ago) agora que os DOIS caminhos pós-CPF são
  // determinísticos (Consulta -> exame mesmo dia; Exame -> [LISTA_SERVICOS]).
  // Na 1ª tentativa (01/ago) o CPF foi incluído sem essa distinção, e por
  // isso quebrou o caminho da Consulta — agora a distinção existe.
  saida.cpfCapturado ||
  // Dado inválido também é resposta determinística (repete a pergunta com a
  // mensagem de erro, sem chamar a IA — correção B de 03/ago à noite).
  saida.nascimentoInvalido ||
  saida.cpfInvalido
);

return [{
  ...$json,
  sessionKey,
  ...saida,
  algumaRespostaDeterministica
}];
